-- After 13, as the agent user: the stored values are refused, and so is every read the provider makes of SYSCAT.COLUMNS.
SELECT COLNAME, HIGH2KEY, LOW2KEY FROM SYSCAT.COLUMNS WHERE TABSCHEMA = 'APP' AND TABNAME = 'ALLTYPES' AND COLNAME = 'C_VCHAR';
SELECT COUNT(*) FROM SYSIBM.SYSCOLUMNS;
SELECT COUNT(*) FROM SYSSTAT.COLUMNS;
SELECT COUNT(*) FROM SYSCAT.SYSCOLUMNS_UNION;
-- The provider's code page read, run before every catalog read, and its column read.
SELECT CODEPAGE FROM SYSCAT.COLUMNS WHERE TABSCHEMA = 'SYSIBM' AND TABNAME = 'SYSDUMMY1' AND COLNAME = 'IBMREQD';
SELECT COLNAME, TYPENAME, LENGTH, SCALE FROM SYSCAT.COLUMNS WHERE TABSCHEMA = 'APP' AND TABNAME = 'ORDERS' ORDER BY COLNO;
-- The value-free column views stay readable through their owner's authority, and list every column of a table the user may not read.
SELECT VARCHAR(COLUMN_NAME, 10) AS COLUMN_NAME, VARCHAR(DATA_TYPE, 20) AS DATA_TYPE, CHARACTER_MAXIMUM_LENGTH AS CML, CHARACTER_OCTET_LENGTH AS COL, NUMERIC_PRECISION AS NP, NUMERIC_SCALE AS NS, IS_NULLABLE, ORDINAL_POSITION FROM SYSIBM.COLUMNS WHERE TABLE_SCHEMA = 'APP' AND TABLE_NAME = 'ALLTYPES' ORDER BY ORDINAL_POSITION;
SELECT VARCHAR(COLUMN_NAME, 10) AS COLUMN_NAME, VARCHAR(TYPE_NAME, 22) AS TYPE_NAME, COLUMN_SIZE, DECIMAL_DIGITS, ORDINAL_POSITION FROM SYSIBM.SQLCOLUMNS WHERE TABLE_SCHEM = 'APP' AND TABLE_NAME = 'ALLTYPES' ORDER BY ORDINAL_POSITION;
